function validate([edges, nums, k]) {
  const n = nums.length;
  if (n < 2 || n > 50000) return 'nums needs 2 to 5 * 10^4 values.';
  if (edges.length !== n - 1) return 'edges needs exactly n - 1 edges.';
  if (nums.some(v => !Number.isInteger(v) || v < -50000 || v > 50000)) return 'Each value is between -5 * 10^4 and 5 * 10^4.';
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is between 1 and 50.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge ends are nodes 0 to n - 1.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree (no cycles).';
    root[a] = b;
  }
  return null;
}

