function subtreeInversionSum(edges, nums, k) {
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  const children = Array.from({ length: n }, () => []);
  const visited = new Array(n).fill(false);
  visited[0] = true;
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (!visited[next]) {
        visited[next] = true;
        children[node].push(next);
        order.push(next);
      }
    }
  }
  // best[node][flip][dist]: largest sum of node's subtree when the inversions above it negate it (flip = 1) or not,
  // and the nearest inverted ancestor is dist edges up (dist = k: far enough away, or there is none).
  const best = Array.from({ length: n }, () => [new Array(k + 1).fill(0), new Array(k + 1).fill(0)]);
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    for (const flip of [0, 1]) {
      const value = flip === 1 ? -nums[node] : nums[node];
      for (let dist = 1; dist <= k; dist++) {
        let keep = value;
        for (const child of children[node]) {
          keep += best[child][flip][Math.min(dist + 1, k)];
        }
        best[node][flip][dist] = keep;
      }
      let invert = -value;
      for (const child of children[node]) {
        invert += best[child][1 - flip][1];
      }
      best[node][flip][k] = Math.max(best[node][flip][k], invert);
    }
  }
  return best[0][0][k];
}

