function subtreeInversionSum(edges, nums, k) {
  // Try every set of inverted nodes and keep the sets that respect the spacing rule.
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
  const parent = new Array(n).fill(-1);
  const stack = [0];
  const visited = new Set([0]);
  while (stack.length) {
    const node = stack.pop();
    for (const next of graph[node]) if (!visited.has(next)) { visited.add(next); parent[next] = node; stack.push(next); }
  }
  let best = -Infinity;
  for (let mask = 0; mask < 1 << n; mask++) {
    let valid = true, total = 0;
    for (let node = 0; node < n; node++) {
      // Walk up to the root, counting inverted nodes on the way and checking their distance to an inverted node.
      let flips = 0;
      for (let up = node, dist = 0; up !== -1; up = parent[up], dist++) {
        if (!(mask >> up & 1)) continue;
        flips++;
        if (dist > 0 && dist < k && (mask >> node & 1)) valid = false;
      }
      total += flips % 2 === 1 ? -nums[node] : nums[node];
    }
    if (valid) best = Math.max(best, total);
  }
  return best;
}

