function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(2, 10);
  // Node i hangs below one of the `reach` nodes created just before it: reach 1 gives a path, a big reach a bushy tree.
  // Large trees stay a few hundred levels deep at most.
  const reach = large ? (rand() < 0.3 ? n : int(8, 30)) : (rand() < 0.3 ? n : int(1, 4));
  const parentOf = [-1];
  for (let i = 1; i < n; i++) parentOf.push(i - 1 - Math.floor(rand() * Math.min(i, reach)));
  // Shuffle the labels of every node except the root.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 1; i--) { const j = int(1, i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push(rand() < 0.5 ? [label[parentOf[i]], label[i]] : [label[i], label[parentOf[i]]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const limit = large ? 50000 : int(2, 10);
  const nums = Array.from({ length: n }, () => int(-limit, limit));
  const k = large ? int(1, 50) : int(1, 5);
  return [edges, nums, k];
}
